const io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){e.target.style.opacity='1';e.target.style.transform='translateY(0)';io.unobserve(e.target)}})},{threshold:.15});
document.querySelectorAll('.isle,.ed,.r-quote').forEach((el,i)=>{el.style.opacity='0';el.style.transform='translateY(24px)';el.style.transition=`opacity .7s ease ${i*60}ms,transform .7s ease ${i*60}ms`;io.observe(el)});
